import"./chunk-2NFLSA4Y.js";var i={transverseWaves:{theory:{concept:"[[A wave is a disturbance that travels through a medium and carries energy without carrying the matter along.]] In a transverse wave the particles of the medium oscillate at right angles to the direction in which the wave travels, as on a stretched rope."},section:{transverse:{title:"Pattern versus material",text:"The wave moves horizontally, but each small marked point moves vertically around its resting position. A marked point does not travel across the screen with a crest. The bright probe is also fixed horizontally; its height changes as the wave passes."},frequency:{title:"Frequency and period",text:"[[Frequency f counts complete oscillations at one fixed point each second.]] Its unit is hertz (Hz): 1 Hz means one cycle per second. Period T is the time for one cycle, so T = 1/f. Increasing frequency makes the fixed probe oscillate more often."},wavelength:{title:"Wavelength",text:"[[Wavelength \u03BB is the distance between neighbouring points in the same phase, such as two crests, measured at one instant.]] The horizontal \u03BB marker spans two points with the same displacement and motion. It is a spatial distance, not the distance that one medium particle travels."},amplitude:{title:"Amplitude",text:"[[Amplitude A is the greatest displacement from the rest line.]] Increasing A makes the wave taller. In this ideal model it does not change its wavelength, frequency or propagation speed."},relation:{title:"The relation v = f\u03BB",text:"During one period, the pattern moves one wavelength. Therefore wave speed v equals frequency multiplied by wavelength: v = f\u03BB. At fixed v, doubling f halves \u03BB. At fixed f, increasing v lengthens \u03BB. The vertical speed of a material point is different from the wave's horizontal propagation speed."},try:{title:"Predict, then test",text:"Set f = 1 Hz and v = 3 m/s. Predict \u03BB. Raise f to 2 Hz without changing v: how far apart are matching crests now? Then change A alone. Watch the highlighted fixed probe and compare its time graph with the shape shown across space."}},param:{frequency:"Frequency",amplitude:"Amplitude",speed:"Wave propagation speed",timeStep:"Simulation timestep"},hint:{frequency:"Oscillations per second at one fixed point.",amplitude:"Maximum vertical displacement from the rest line.",speed:"How fast a crest travels horizontally through the medium."},preset:{slow:"0.5 Hz",one:"1 Hz",fast:"2 Hz"},measure:{wavelength:"Wavelength",period:"Period",displacement:"Probe displacement",transverseVelocity:"Probe vertical velocity",maxTransverseSpeed:"Maximum point speed"},variable:{position:"Horizontal position",displacement:"Vertical displacement"},view:{particles:"Medium points",dimensions:"Amplitude and wavelength",direction:"Travel direction",travel:"Pattern travels \u2192",probe:"Fixed probe"},graph:{displacement:"Probe displacement over time",velocity:"Probe vertical velocity over time"},formula:{speed:"Wave speed, frequency and wavelength",period:"Time for one oscillation",wave:"Right-travelling sinusoidal wave",velocity:"Vertical velocity at a fixed point"},assumption:{medium:"An ideal uniform, nondispersive medium is assumed. Speed and amplitude stay constant; damping, reflections, interference and nonlinear effects are omitted.",window:"The diagram shows a window into an already established wave, not a finite string starting to move. Points are illustrative samples and their size is not to scale.",reset:"Changing a parameter starts a new steady-wave experiment. Transitions between two settings are not simulated; the wave is evaluated analytically at fixed time steps."},challenge:{short:{title:"A shorter wave",description:"Make a wavelength of 1.5 m.",hint:"With the beginner speed of 3 m/s, choose a frequency of 2 Hz."},period:{title:"Two seconds per cycle",description:"Make the period 2 s.",hint:"Frequency is the reciprocal of period."},amplitude:{title:"Taller but equally spaced",description:"Make the amplitude 0.75 m while keeping wavelength at 3 m.",hint:"Raise amplitude and return frequency to 1 Hz."},speed:{title:"Four-metre wavelength",description:"Make the period 2 s and wavelength 4 m.",hint:"Choose 0.5 Hz and a propagation speed of 2 m/s."},velocity:{title:"Fast-moving medium points",description:"Make the maximum vertical point speed exceed 8 m/s while propagation speed is at most 2 m/s.",hint:"High frequency and amplitude increase the point's vertical speed."}}}},a={sim:i};export{a as default,i as sim};
